import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';

/**
 * Get overdue invoices sorted by most overdue first.
 * @param {Array<{ number: string, customerId: string, status: string, dueDate: string, payments?: Array, lines: Array, voucher?: { amount: number } }>} invoices
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter((invoice) => invoice.status === 'issued' || invoice.status === 'partially_paid')
    .filter((invoice) => invoice.dueDate < asOf)
    .map((invoice) => ({
      number: invoice.number,
      customerId: invoice.customerId,
      dueDate: invoice.dueDate,
      daysOverdue: daysBetween(invoice.dueDate, asOf),
      due: balanceDue(invoice),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

input.new_string:
import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { lineTotal, lineDiscount, lineVat } from './invoices.js';

/**
 * Get overdue invoices sorted by most overdue first.
 * @param {Array<{ number: string, customerId: string, status: string, dueDate: string, payments?: Array, lines: Array, voucher?: { amount: number } }>} invoices
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter((invoice) => invoice.status === 'issued' || invoice.status === 'partially_paid')
    .filter((invoice) => invoice.dueDate < asOf)
    .map((invoice) => ({
      number: invoice.number,
      customerId: invoice.customerId,
      dueDate: invoice.dueDate,
      daysOverdue: daysBetween(invoice.dueDate, asOf),
      due: balanceDue(invoice),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Get VAT summary grouped by rate.
 * @param {Array<{ status: string, lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const vatByRate = {};

  invoices
    .filter((invoice) => invoice.status === 'issued' || invoice.status === 'partially_paid' || invoice.status === 'paid')
    .forEach((invoice) => {
      invoice.lines.forEach((line) => {
        const rate = line.vatRate;
        const base = lineTotal(line) - lineDiscount(line);
        const vat = lineVat(line);

        if (!vatByRate[rate]) {
          vatByRate[rate] = { base: 0, vat: 0 };
        }
        vatByRate[rate].base += base;
        vatByRate[rate].vat += vat;
      });
    });

  return Object.entries(vatByRate)
    .map(([rate, { base, vat }]) => ({
      rate: parseFloat(rate),
      base,
      vat,
    }))
    .sort((a, b) => b.rate - a.rate);
}

